INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_PROMO_MIST','The Living Mist');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_PROMO_MIST_HELP','+1 Science per worked, unpillaged Marsh, capped at +4 per city. +1 Culture with two owned Marsh plots within three hexes. Military units gain +10% defense on Marsh.');
