INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_PROMO_LINEAGE_HELP','+1 Sight, double Marsh movement and +15% additional defense on Marsh. Unique properties persist through upgrades.');
