INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_CIV_PEDIA','Greyfen''s watchtowers and raised paths thread through the mist. Mirelle guards their hidden approaches and studies the wetland ecology.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_STRATEGY','Settle marshy waterways near good production tiles. Assign citizens to work unpillaged Marsh after building enough food infrastructure. Defend in the wetlands where both military bonuses can apply.');
