INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_FALLBACK_1','We have heard your terms.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_FIRST_GREETING_1','Welcome to Greyfen. Stay on the wooden paths. The marsh has a habit of remembering those who wander.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_DECLAREWAR_1','You have studied our borders. You have counted our soldiers. But you have forgotten to count the marsh.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D027_DEFEATED_1','The fog lifts... and for the first time, I can see the end.');
